'use strict';
function estimateExportSize({format=$('videoFormat').value,resolution=$('resolution').value,range=readExportRange()}={}){const d=exportGeometry(resolution),duration=range.end-range.start,pixels=d.width*d.height,scale=pixels/(1920*1080);if(format==='gif')return{low:duration*pixels*.025,high:duration*pixels*.25,label:'GIF · 256 colours · silent'};const base=format==='webm'?5:8,mbps=clamp(base*scale**.8,.7,80),audio=tracks().length?.192:0;return{low:duration*(mbps*.5+audio)*1e6/8,high:duration*(mbps*1.8+audio)*1e6/8,label:exportFormatNames[format]}}
const exportReview=document.createElement('section');exportReview.id='exportReview';exportReview.className='export-review';exportReview.innerHTML='<strong>Output check</strong><dl id="exportReviewDetails"></dl><p class="note">Size is an estimate. Artwork detail, movement and duration affect the final file.</p>';$('exportOutputSummary').after(exportReview);
const summaryBeforeReview=updateExportSummary;updateExportSummary=function(){summaryBeforeReview();const el=$('exportReviewDetails');el.replaceChildren();try{const format=$('videoFormat').value,range=readExportRange(),g=exportGeometry($('resolution').value),size=estimateExportSize(),seconds=range.end-range.start,rows=[['File',size.label+' · .'+format],['Dimensions',g.width+' × '+g.height+' pixels'],['Frame rate',format==='gif'?'30 fps source · palette loop':'30 fps'],['Duration',seconds.toFixed(2)+' seconds · '+Math.ceil(seconds*30)+' rendered frames'],['Estimated size',(size.low/1e6).toFixed(1)+'–'+(size.high/1e6).toFixed(1)+' MB'],['Audio',format==='gif'?'Silent':tracks().length+' timeline audio clips mixed'],['Preview quality','Export uses the dimensions above, independent of playback preview quality']];for(const [label,value]of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;el.append(dt,dd)}}catch(e){el.textContent=e.message}};
// Existing event listeners retain the original function reference; refresh the review too.
for(const id of ['exportScope','exportRangeStart','exportRangeEnd','videoFormat','resolution'])$(id).addEventListener('change',()=>updateExportSummary());
const exportBeforeReview=$('export').onclick;$('export').onclick=(...args)=>{const out=exportBeforeReview?.(...args);updateExportSummary();return out};updateExportSummary();
